create table FM_BRANCH (BRANCH VARCHAR(30) not null  ,AREA_CODE VARCHAR(4) null  ,FX_ORGAN_CODE VARCHAR(14) null  ,EOD_FLAG VARCHAR(20) null  ,FTA_FLAG VARCHAR(1) null  ,CITY VARCHAR(6) null  ,BRANCH_TYPE VARCHAR(1) not null  ,FTA_CODE VARCHAR(10) null  ,START_DATE TIMESTAMP(3) not null  ,BRANCH_NAME VARCHAR(200) not null  ,IP_ADDR VARCHAR(200) null  ,PBOC_FINANCING_NO VARCHAR(14) null  ,DISTRICT VARCHAR(6) null  ,CREATE_DATE TIMESTAMP(3) null  ,CITY_BRANCH_FLAG VARCHAR(1) not null  ,HIERARCHY_CODE VARCHAR(3) null  ,BRANCH_SHORT VARCHAR(30) not null  ,POSTAL_CODE VARCHAR(6) null  ,COMPANY VARCHAR(20) null  ,END_DATE TIMESTAMP(3) null  ,STATE VARCHAR(6) not null  ,ATTACHED_TO VARCHAR(30) null  ,COUNTRY VARCHAR(3) not null  ,PROFIT_CENTER VARCHAR(20) null  ,SUB_BRANCH_CODE VARCHAR(30) null  ,TRAN_TIMESTAMP VARCHAR(26) not null  ,INTERNAL_CLIENT VARCHAR(22) null  , primary key(BRANCH));